<script setup>
import { ref, onMounted, onBeforeUnmount } from 'vue'
import { BookOpen, GraduationCap, ShieldCheck } from 'lucide-vue-next'
import api from './api'
import { pendingCount, startSyncListeners } from './offline'
const online=ref(navigator.onLine); const pending=ref(0); let stopSync=null; const username=ref('');const password=ref('');const error=ref('');const loading=ref(false);const loggedIn=ref(Boolean(localStorage.getItem('techbok_student_access')));const showLogin=ref(false);const courses=ref([]);const user=ref(null)
async function login(){loading.value=true;error.value='';try{const r=await api.post('auth/token/',{username:username.value,password:password.value});localStorage.setItem('techbok_student_access',r.data.access);if(r.data.refresh)localStorage.setItem('techbok_student_refresh',r.data.refresh);loggedIn.value=true;await load();if(stopSync)stopSync();stopSync=startSyncListeners(async()=>pending.value=await pendingCount())}catch(e){error.value='Unable to sign in. Please check your credentials.'}finally{loading.value=false}}
async function load(){try{const [u,c]=await Promise.all([api.get('auth/me/'),api.get('courses/?status=active')]);user.value=u.data;courses.value=c.data.results||c.data}catch(e){if(e.response?.status===401){error.value='Your session has expired. Please sign in again.';logout()}else{error.value='The server is unavailable. Previously loaded information may be unavailable until you reconnect.'}}}
function openLogin(){showLogin.value=true;error.value='';username.value='';password.value=''}
function logout(){localStorage.removeItem('techbok_student_access');localStorage.removeItem('techbok_student_refresh');loggedIn.value=false;showLogin.value=false;username.value='';password.value='';error.value='';user.value=null;courses.value=[]}
onMounted(()=>{window.addEventListener('online',()=>online.value=true);window.addEventListener('offline',()=>online.value=false);window.addEventListener('techbok-outbox-changed',async()=>pending.value=await pendingCount()); if(loggedIn.value){load();pendingCount().then(n=>pending.value=n);stopSync=startSyncListeners(async()=>pending.value=await pendingCount())}}); onBeforeUnmount(()=>{if(stopSync)stopSync()})
</script>
<template><main v-if="!loggedIn && !showLogin" class="public-home"><header class="public-header"><div class="brand"><img class="portal-logo" src="/techbok-logo.png" alt="TechBoK logo"><div><strong>TechBoK</strong><span>TECHNOLOGY EDUCATION</span></div></div><button class="primary login-link" @click="openLogin">Student sign in</button></header><section class="public-hero"><div class="hero-copy"><p class="eyebrow">TechBoK INSTITUTE</p><h1>Practical technology skills for a changing world</h1><p>Explore technology training programmes designed to build practical knowledge, confidence and career-ready skills.</p><button class="primary hero-button" @click="openLogin">Access Student Portal</button></div><div class="hero-art"><img src="https://images.unsplash.com/photo-1522202176988-66273c2fd55f?auto=format&fit=crop&w=1400&q=88" alt="Students working together on laptops"></div></section><section class="public-intro"><h2>Learn. Practise. Build.</h2><p>Discover TechBoK programmes and access your learning workspace in one place.</p></section><footer>© {{new Date().getFullYear()}} TechBoK <span>Learn practical. Build confidently.</span></footer></main><main v-else-if="!loggedIn" class="login-wrap"><section class="login-card"><div class="brand-mark"><GraduationCap :size="25"/></div><p class="eyebrow">TechBoK STUDENT PORTAL</p><h1>Your learning, in one place.</h1><p class="muted">Sign in to access your TechBoK learning workspace.</p><form @submit.prevent="login"><label>Username<input v-model="username" autocomplete="off" required placeholder="Your username"></label><label>Password<input v-model="password" type="password" autocomplete="new-password" required placeholder="Your password"></label><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="loading">{{loading?'Signing in…':'Sign in'}}</button></form><p class="footnote">Secure access for enrolled TechBoK students</p></section></main><main v-else class="portal"><header><div class="brand"><div class="brand-mark small"><GraduationCap :size="21"/></div><div><strong>TechBoK</strong><span>STUDENT PORTAL</span></div></div><div class="portal-status"><span class="status-dot" :class="{offline:!online}"></span>{{online?'Online':'Offline'}} · {{pending}} pending</div><button class="outline" @click="logout">Sign out</button></header><section class="welcome"><p class="eyebrow">YOUR LEARNING SPACE</p><h1>Welcome{{user?.first_name?' back, '+user.first_name:''}}</h1><p>Keep your learning journey organised and moving forward.</p></section><section class="info-card"><div class="iconbox"><ShieldCheck/></div><div><h2>Your student workspace</h2><p>Authentication is connected. Personal academic records, fee statements, attendance and results will appear here as those modules are implemented.</p></div></section><section class="courses"><div class="section-title"><div><h2>Explore TechBoK courses</h2><p>Available courses from the current catalogue</p></div><BookOpen/></div><div v-if="!courses.length" class="empty">No active courses are listed yet. Please check back later or contact the institute.</div><div class="course-grid"><article v-for="c in courses" :key="c.id" class="course-card"><div class="course-symbol"><BookOpen/></div><span class="course-code">{{c.code}}</span><h3>{{c.name}}</h3><p>{{c.description||'Practical learning designed to build your technology skills.'}}</p><div class="course-meta"><span>{{c.duration_weeks?c.duration_weeks+' weeks':'Flexible duration'}}</span><span>{{c.delivery_mode.replace('_',' ')}}</span></div></article></div></section><footer>© {{new Date().getFullYear()}} TechBoK <span>Learn practical. Build confidently.</span></footer></main></template>
